@_dataclass(kw_only=True)
class ConversationEntry(Model):
    """One entry of a session transcript — what GET /sessions/{sessionId}/messages serves in both
    `messages` and `items` (types/session.ts ConversationEntry, enriched on read by sessions.ts
    with the run's metrics and cost). Measured 2026-09-10 on e2e-canon: a user turn carries
    role, content, run_id, timestamp, compacted, importance; an assistant turn adds tool_calls,
    thinking, run_metrics, cost_usd.
    """

    message_id: str
    """The stable id of this entry — derived on read (lib/message-ids.ts), never stored, so every
    transcript has it: the first user turn of a run is `{run_id}`, the first assistant reply
    `{run_id}-reply`, further replies `{run_id}-reply-2`…, a second human turn of the same run
    `{run_id}-user-2`… (lib/message-ids.ts:16-19), tool results `{run_id}-tool-N` and system
    entries `{run_id}-system-N` numbered from 1 (the first is `-tool-1`, never bare `-tool`).
    Counted per run over the whole history before compaction, so it does not move. This is the
    canonical `message_id` for reactions (PUT /runs/{runId}/feedback), bookmarks
    (/agents/{agentId}/bookmarks/{messageId}) and annotations (POST
    /sessions/{sessionId}/annotations); it is a safe path segment.
    """

    role: PublicSessionViewMessageRole

    content: JsonValue
    """The text, or content parts for a multimodal turn (types/llm.ts MessageContent). v1 emits the
    string arm: every writer (renderUserTurn, SessionMessageSchema.content,
    ImportSessionMessageSchema) stores a string, and every stored entry on production is one (8
    427 of 8 427, measured 2026-09-11). The array arm is the LLM wire type (types/llm.ts
    MessageContent) the schema inherits; a v2 server accepts only the string.
    """

    run_id: str

    timestamp: str

    compacted: Optional[bool] = None

    tool_calls: Optional[List[ConversationEntryToolCall]] = None
    """Persisted on assistant entries when the run executed tools. Reload re-paints these blocks
    underneath the assistant turn (matches what the SSE stream renders during the live run).
    """

    thinking: Optional[str] = None
    """Reasoning / thinking content (DeepSeek `reasoning_content`, Anthropic extended thinking,
    GLM/Qwen `<think>` blocks). Persisted on assistant entries so reload re-paints the Thinking
    section above the assistant text.
    """

    importance: Optional[ConversationEntryImportance] = None

    attachments: Optional[List[ConversationEntryAttachment]] = None

    metadata: Optional[ConversationEntryMetadata] = None
    """Present only on an entry that is not an ordinary turn. Today: the morning summary — an
    assistant entry the head agent posts at 08:00 tenant-local time (since 2026-10-19) with
    `kind: "daily_summary"` and the local `date` it summarises from; no run produced it, so its
    `run_id` is `morning-summary-<date>`.
    """

    run_metrics: Optional[ConversationEntryRunMetrics] = None
    """On an assistant entry: the run's metrics as served by GET /runs/{runId} (sessions.ts
    publicRunMetrics).
    """

    cost_usd: Optional[float] = None
    """On an assistant entry, when the run recorded a cost."""

    from_todo: Optional[bool] = None
    """The reply came from a run a Todo triggered. Stored on the entry since 2026-10-16 (with
    `author_agent_id` / `author_name`), so it survives the run's deletion; derived from the run
    for older entries.
    """

    output_truncated: Optional[bool] = None
    """The model ran out of output tokens — see RunOutput.output_truncated."""

    author_agent_id: Optional[str] = None
    """With `from_todo`: the agent that did the work, stored on the entry when the reply was
    written (since 2026-10-16), so it outlives the run and the agent.
    """

    author_name: Optional[str] = None
    """With `from_todo`: that agent's name when the reply was written."""

    error_code: Optional[str] = None
    """On an assistant entry whose run failed — today a run stopped by the token cap, whose partial
    answer is this entry's `content`. The run's own `error_code`. Since 2026-10-16.
    """

    error_details: Optional[JsonObject] = None
    """With `error_code`: the run's `error_details` without `partial_response` (that is `content`),
    e.g. `limit_tokens` and `used_tokens`.
    """


