@_dataclass(kw_only=True)
class Error(Model):
    """RFC 9457 problem document; `correlation_id` is the request id — the same value as this
    response's `X-Request-Id` header and as `requestId` in the server's log lines for the
    request. The server chooses it once at ingress: the caller's own `X-Request-Id` when it is
    8–128 characters of `[A-Za-z0-9._:-]` starting with a letter or digit, otherwise a fresh
    UUIDv7. Present on every problem document. `correlationId` is the same value for the
    compatibility window.
    """

    type: str

    title: ErrorTitle
    """The HTTP reason phrase of `status` — one dictionary for every status the platform answers
    with (lib/error-titles.ts; the enum is built from it). The one deliberate exception: 422
    says "Validation Error", as it always has. Never an exception class name; that lives in
    `code`.
    """

    status: int

    detail: str
    """The sentence a person reads — specific to this occurrence, never empty, never a repeat of
    `title`. On a 500 it is the fixed sentence the sanitizer allows; 501–504 carry the handler's
    own operator guidance.
    """

    code: Optional[ErrorCode] = None
    """What a client should DO about this, as a value it can switch on — `detail` is for the person
    reading. The enum is built from the one dictionary in `types/error-codes.ts`, so the
    document and the wire cannot drift apart. Two casings are on the wire and both are
    load-bearing: SCREAMING_SNAKE came from the `UarpError` hierarchy, lower_snake from the
    hand-written limit refusals, and clients match on each exactly. Present on every 400, 401,
    404, 405, 409, 413, 422 and 429: a refusal whose call site names no finer class carries its
    status's fallback (`INVALID_REQUEST`, `AUTH_ERROR`, `NOT_FOUND`, `METHOD_NOT_ALLOWED`,
    `CONFLICT`, `PAYLOAD_TOO_LARGE`, `VALIDATION_ERROR`, `RATE_LIMIT_EXCEEDED`) — since
    2026-10-11, before which most 401/404/405 carried none. A 403 carries `FORBIDDEN` or a finer
    code only when its call site names one. Other statuses: absent when there is no
    machine-readable class.
    """

    correlation_id: Optional[str] = _field(default=None, metadata={"wire": "correlationId"})
    """Request ID for tracing Deprecated spelling of `correlation_id` — the same value, kept for
    the compatibility window and removed in the next breaking release (the one that moves
    `X-API-Version`). Read `correlation_id`.

    Deprecated.
    """

    errors: Optional[List[ErrorError]] = None
    """Field-level validation errors (present on 422 responses)"""

    error: Optional[str] = None
    """Deprecated twin, present only on refusals that answered a bare `{error}` body before
    2026-10-02: the MFA step-up 401 (`mfa_required`), the public chat's 429s and some governance
    refusals (the same sentence as `detail`). Kept unchanged for the compatibility window,
    removed in the next breaking release (the one that moves `X-API-Version`); such a response
    carries `Deprecation: true`. Read `code` and `detail`.

    Deprecated.
    """

    reason: Optional[ErrorReason] = None
    """MFA step-up only (`code: mfa_required`): `not_enrolled` — enrol a second factor; `stale` —
    verify it again.
    """

    retry_after: Optional[int] = None
    """Public chat 429s only: seconds until a retry can succeed, the same value as the
    `Retry-After` header.
    """

    correlation_id_: Optional[str] = _field(default=None, metadata={"wire": "correlation_id"})
    """Request ID for tracing"""


