@_dataclass(kw_only=True)
class GetRunResponse(Model):
    """`GetRunResponse` model."""

    execution_requirements: Optional[QualificationExecutionRequirementsV2] = None
    """Sponsored qualification runs only: the requirements the run was admitted under, stored as
    accepted.
    """

    recovery_expires_at_unix: Optional[int] = None
    """Sponsored qualification runs only: until when the run is recoverable by its client request
    id.
    """

    sponsorship_grant_id: Optional[str] = None
    """Sponsored qualification runs only: the grant that paid for it."""

    execution_mode: Optional[RunExecutionMode] = None
    """Absent for platform-dispatched cloud runs. `bridge` is written by the platform when a local
    agent takes the run (run-dispatch.ts, bridge.ts); `async` is only ever an echo of a
    client-supplied value and has never been stored on production (measured 2026-09-10 over 8605
    run records: absent 7738, bridge 867, async 0).
    """

    run_id: str

    tenant_id: str

    agent_id: str

    session_id: Optional[str] = None

    status: RunStatus

    input: Optional[JsonObject] = None

    output: Optional[RunOutput] = None
    """Run output — the same object rides in run events and in a public session's stream
    (RunOutput). When a run is truncated by its step-budget cutoff (output.truncated === true)
    AND the platform has UARP_CONTINUATION_TOKEN_KEY configured, output.continuation_token
    carries an opaque HMAC-signed token that resumes the run via POST /runs/{id}/continue. With
    no key configured no token is minted and the field is absent; the token is an opaque string
    to every client.
    """

    metrics: Optional[RunMetrics] = None

    error: Optional[str] = None
    """The sentence a person reads. English on every deployment — nothing here varies by
    `Accept-Language` — so branch on `error_code`, not on this.
    """

    error_code: Optional[str] = None
    """Why the run failed, as a value from the `code` dictionary (see the `Error` schema's enum).
    Absent when the failure carries nothing a client can branch on — which is deliberate: a code
    meaning "something went wrong" would be worse than none. Populated since 2026-09-21; before
    that a client had to regex-test `error`. `approval_rejected` (since 2026-09-22) means a
    person refused the tool call the run was waiting on — `status` is still `failed`, and
    `error` is the reviewer's own reason.
    """

    error_details: Optional[JsonObject] = None
    """Numbers the code cannot carry: `retry_after_ms` with `provider_circuit_open`,
    `quota_exhausted` with `provider_rate_limited`, `stale_seconds` with `run_input_timeout`,
    `limit_usd` and `spent_usd` with `BUDGET_EXCEEDED` (beside the older `max_cost_usd`,
    `accumulated_cost_usd` and `cap_source`), `limit_ms` and `elapsed_ms` with
    `MAX_DURATION_EXCEEDED` (both since 2026-09-23). `limit_tokens`, `used_tokens` and, when the
    model had written anything, `partial_response` (its text so far, at most 8000 characters)
    with `MAX_TOKENS_EXCEEDED` (since 2026-10-16). Never a provider id — this reaches a screen,
    and the product does not name the model it picked.
    """

    approvals: Optional[List[GetRunResponseApproval]] = None
    """Every human decision on a tool approval this run waited for, oldest first. Absent when the
    run never waited for one. Recorded since 2026-09-22; before that an approved call left no
    trace on the run.
    """

    review: Optional[GetRunResponseReview] = None
    """The latest person's verdict on this run's RESULT (`POST /runs/{runId}/review`, since
    2026-10-19) — not a tool approval, which is `approvals`. Absent until the result is
    reviewed. The full record, with the comment and anchors, is `GET /runs/{runId}/review`.
    """

    created_at: str

    started_at: Optional[str] = None

    completed_at: Optional[str] = None

    team_run_id: Optional[str] = None
    """Team run ID if part of a team execution"""

    metadata: Optional[JsonObject] = None
    """User-supplied metadata"""

    step_seq: Optional[int] = None
    """Current step sequence number"""

    artifacts: Optional[List[Artifact]] = None
    """Run artifacts"""

    resource_limits: Optional[GetRunResponseResourceLimits] = None
    """Resource limits for the run"""

    changed_files: Optional[List[str]] = None
    """Workspace paths this run WROTE, sorted, present only when the request carries
    `?changed_files=true`. Recorded per (run, path) at write time, so a file rewritten three
    times appears once and two concurrent tool calls cannot lose one another's entry.

    It is a record of writes, not a diff: a path the run DELETED or moved is not here, and
    neither is a change made by something else while the run was going. Recording is best-effort
    after the write has already succeeded — a failure to record is logged and leaves the list
    short rather than failing the edit — so treat it as "at least these" rather than proof that
    nothing else changed. Capped at 500 paths. Rows expire 30 days after the run.
    """

    pending_approvals: Optional[List[PendingApproval]] = None
    """Tool calls the run is blocked on, taken from the most recent `run.awaiting_approval` event.
    ABSENT — not empty — when the run is not awaiting approval, and absent too if the scan
    fails, which is deliberate: a failed scan must not turn a readable run into an error.
    """

    pending_input: Optional[GetRunResponsePendingInput] = None
    """The question the run is blocked on, taken from the most recent `run.awaiting_input` event
    (runs.ts:673-681). Like `pending_approvals` it is ABSENT rather than empty when the run is
    not awaiting input. A squad chat reads this to render the prompt; the document never
    mentioned it, so a client written from the document alone showed a blocked run as merely
    running.
    """


