@_dataclass(kw_only=True)
class Mission(Model):
    """A Mission Execution Framework run: a goal decomposed into objectives, executed under an
    authorization gate with checkpoints and an after-action review. Sent by every mission
    endpoint that answers with the record itself.
    """

    mission_id: str

    tenant_id: str

    session_id: str
    """Chat session the mission was started from."""

    created_by: str
    """User id, or an agent id when a sub-mission was spawned by an agent."""

    goal: str
    """The requester's goal, verbatim."""

    classification: MissionClassification
    """Why MEF took the request. `quick_reply` never reaches execution."""

    status: MissionStatus
    """Lifecycle state. `completed`, `failed` and `aborted` are terminal."""

    objective_ids: List[str]
    """Root objective ids in plan order."""

    checkpoint_ids: List[str]
    """Appended chronologically as objectives verify; a resume replays from the last one."""

    aar_id: Optional[str] = None
    """Set once the after-action review is finalized — see GET /missions/{missionId}/aar."""

    metrics: Optional[MissionMetrics] = None

    outcome: Optional[MissionOutcome] = None
    """Terminal outcome. `partial` means some objectives verified and some did not."""

    result_summary: Optional[str] = None
    """English prose. For a client that branches or translates, read `result_code`."""

    result_code: Optional[MissionResultCode] = None
    """`result_summary` as a code, written with it and cleared with it (a summary written without a
    code clears the previous one). Absent on summaries written before 2026-09-23.
    `all_objectives_verified` (details `verified`), `objectives_failed` (`failed`, `total`),
    `planning_failed`, `aborted_by_signal`, `aborted_by_operator` (the operator's reason, when
    given, is the summary), `watchdog_stuck` (`stuck_status`, `stuck_minutes`),
    `paused_by_operator`, `queued_walk_ceiling` (planned, then paused because the tenant was
    already running its maximum concurrent missions — resumable with `POST
    /missions/{id}/resume`), `resumed_by_operator`, `authorized_by_operator`.
    """

    result_details: Optional[JsonObject] = None
    """The numbers `result_summary` carries, keyed per `result_code` (see there). Absent when the
    code carries none.
    """

    failed_objective_ids: Optional[List[str]] = None
    """Subset of objective_ids that failed verification."""

    deadline: Optional[str] = None
    """ISO 8601 hard deadline the runtime enforces against."""

    created_at: str

    updated_at: str

    started_at: Optional[str] = None
    """Set when the mission first enters `executing` — when work begins. Absent while it waits at
    `awaiting_authorization`. Since 2026-09-23; before, it was set when the status first left
    `draft`, i.e. at creation, so the wait for authorization counted as execution.
    """

    completed_at: Optional[str] = None
    """Set when the status becomes terminal."""


@_dataclass(kw_only=True)
class MissionMetrics(Model):
    """Aggregated spend for the whole mission. Written on the terminal transition, so it is absent
    while the mission is still running.
    """

    total_cost_usd: float

    total_tokens: int

    total_duration_ms: int

    llm_calls: int

    retries: int
    """Objective retries across the mission — a strike counter, not an HTTP retry count."""


@_dataclass(kw_only=True)
class MissionStartResponse(Model):
    """What POST /missions answers. `plan` is echoed back only when the server planned the mission
    from a goal.
    """

    mission_id: str

    objective_ids: List[str]
    """Persisted objective ids, in plan order."""

    classification: MissionStartResponseClassification
    """The intake decision. A `quick_reply` mission is recorded but is not mission work.
    `classification` is the value the mission was stored with (its plan's), the same as `GET
    /missions/{missionId}` reports; `score` and `confidence` are the goal-text heuristic's
    signal and may disagree with it — since 2026-09-23 they no longer override it (before, this
    field carried the heuristic's verdict, e.g. `quick_reply` for a stored `mission`).
    """

    plan: Optional[PlannedMission] = None

    run_started: Optional[bool] = None
    """Whether this request also started executing the mission. `true` when planning put it in
    `executing` (the plan needed no authorization) and a walk began — progress then arrives on
    `/missions/{missionId}/events`, and a later `POST /run` answers `already_running` while it
    is in flight. `false` when the mission is `awaiting_authorization` (authorize, then `POST
    /run`) or when the tenant is at its concurrent-mission ceiling (the mission stays
    `executing`; `POST /run` starts it). Added 2026-09-22: before it, a mission reported
    `executing` and dispatched nothing until a separate `POST /run`.
    """


