@_dataclass(kw_only=True)
class PatchTenantRequest(Model):
    """A partial tenant. Fields not named are left alone — except `social_links`, which is REPLACED
    wholesale rather than merged, so a PATCH carrying one platform leaves the tenant with that
    one platform and nothing else. Send every link you want to keep, `custom` included.

    `social_links` values are filtered, not rejected: a url that does not match
    `^https?://.{3,500}$` is dropped and the request still answers 200. Length is applied BEFORE
    the pattern, which is the case worth knowing about — a url longer than 500 characters is CUT
    to 500 and the cut value then matches, so it is STORED TRUNCATED rather than refused. A
    working-looking link that goes somewhere else is worse than a missing one, and a client
    checking only whether the key came back cannot see it.

    Nothing here is hidden: the response is the tenant AS STORED, so compare what you sent
    against what came back — values and lengths, not just which keys are present. No second GET
    is needed. See `Tenant.social_links` for the field-by-field shape.

    Documented 2026-09-18. The 2026-09-17 pass wrote this onto the Tenant RESPONSE schema and
    left the request body an untyped `object`: right words, wrong end of the call. Caught by the
    SDK lane, whose generator produced a typed `Tenant.social_links` beside a `patch(body:
    JsonObject)` that could not describe what to send.
    """

    name: Optional[str] = None

    slug: Optional[str] = None
    """The public handle. An invalid slug answers 422; one held by another tenant answers 409."""

    description: Optional[str] = None

    logo_url: Optional[str] = None
    """Trimmed and cut to 2000 characters."""

    branding: Optional[TenantBranding] = None
    """Shallow-merged into the stored branding."""

    public: Optional[bool] = None

    public_agent_id: Optional[str] = None
    """An agent of this tenant (404 otherwise); setting it publishes that agent. Null clears."""

    published_agent_ids: Optional[List[str]] = None
    """Replaced whole. More than 50 answers 422. Null clears."""

    public_settings: Optional[TenantPublicSettings] = None
    """Shallow-merged."""

    settings: Optional[JsonObject] = None
    """Shallow-merged. `legal_hold`, `suspended`, `max_concurrent_runs_override`, `default_model`
    and `default_provider` are stripped before the write.
    """

    head_agent_id: Optional[str] = None
    """An agent of this tenant (404 otherwise). Null clears."""

    shared_workspace_id: Optional[str] = None
    """A workspace of this tenant (404 otherwise). Null clears."""

    custom_domain: Optional[PatchTenantRequestCustomDomain] = None
    """`{domain}` to claim a domain, null to release it. Needs the pro plan (403 without it) and a
    public profile — `public: true`, here or already stored (422 without it).
    """

    marketplace_listing: Optional[PatchTenantRequestMarketplaceListing] = None
    """Replaced whole (its `stats` and `published_at` are kept)."""

    legal_hold: Optional[bool] = None
    """Can be set; a set hold cannot be cleared here (403)."""

    social_links: Optional[TenantSocialLinks] = None

    additional_properties: Dict[str, Any] = _field(default_factory=dict, metadata={"additional": True})
    """Members the server sent that the document does not name, as sent."""


