@_dataclass(kw_only=True)
class PermissionSetUpdate(Model):
    """Body of PUT /governance/permissions/{agentId}. Every field optional: a field the body omits
    keeps its stored value (mergePermissionSet), and only a first write falls back to the
    defaults. `agent_id`, `tenant_id`, `created_at`, `updated_at` are set by the server and
    ignored in the body.
    """

    allowed_tools: Optional[List[str]] = None
    """Sending this field REPLACES the stored list (the handler stores the array as sent, it does
    not merge). A NON-EMPTY list limits the agent's own runs to exactly these tool names (since
    2026-10-12): every other tool is neither offered to the model nor executed when called. An
    EMPTY list puts no limit on the agent's own runs (the same rule as `mcp.allowed_tools` on
    the agent) — but for spawning it still means no child tool is permitted, since a child's
    tools must be a subset of this list. Before 2026-10-12 the list was read only by the spawn
    gate and did not limit the agent itself.
    """

    allowed_roles: Optional[List[str]] = None
    """Sending this field REPLACES the stored list (the handler stores the array as sent, it does
    not merge).
    """

    resource_permissions: Optional[List[ResourcePermission]] = None
    """Sending this field REPLACES the stored list (the handler stores the array as sent, it does
    not merge).
    """

    max_budget_per_run_usd: Optional[float] = None
    """Hard cap (USD) on the cost of each of this agent's own runs, and the ceiling a spawned
    child's budget may not exceed. The run's effective cost ceiling is the smaller positive of
    this and resource_limits.max_cost_usd (or the platform ceiling); a run that crosses it fails
    with error_code BUDGET_EXCEEDED and error_details.cap_source "permission_set" or
    "resource_limits". 0 means no cap from this field; null clears the cap and is stored as 0.
    Unlike the other fields, a present value of the wrong type or a negative number is refused
    with 422 and nothing is written — it is a spend cap, and a silent fallback here stored a
    string "0.0005" as 1.0.
    """

    max_spawn_depth: Optional[int] = None

    can_spawn: Optional[bool] = None

    can_self_modify: Optional[bool] = None

    parent_agent_id: Optional[str] = None


